import assert from "node:assert/strict";
import { test } from "node:test";
import { createStructuredCommands, defaultJqLimits, structuredCommands } from "../../../src/commands/structured/index.js";
import { CommandRegistry, type ByteSource, type PluginHost } from "../../../src/contracts/index.js";
import { MemoryFileSystem } from "../../../src/fs/memory/index.js";
import { chunks, run } from "./helpers.js";

const streamCases: [string[], string, string, number][] = [
  [["-c", "."], '1 2\n{"a":3}', '1\n2\n{"a":3}\n', 0],
  [["-c", "."], '{}[]"x""y"', '{}\n[]\n"x"\n"y"\n', 0],
  [["-c", "."], '1{}', '1\n{}\n', 0],
  [["-c", "."], '1true', '', 5],
  [["-c", "."], 'truefalse', '', 5],
  [["-c", "."], '1\n{"bad":', '1\n', 5],
  [["-sc", "."], '1\n{"bad":', '', 5],
  [["-sc", "."], '', '[]\n', 0],
  [["-nsc", "."], 'INVALID', 'null\n', 0],
  [["-ec", "."], '', '', 4],
  [["-ec", "empty"], 'null', '', 4],
  [["-ec", "."], 'true\nnull', 'true\nnull\n', 1],
  [["-ec", "."], 'null\n0', 'null\n0\n', 0],
  [["-ec", "select(.!=null)"], '1\nnull', '1\n', 0],
  [["-ec", "select(.!=null)"], 'false\nnull', 'false\n', 1],
  [["-rec", '"false"'], 'null', 'false\n', 0],
  [["-rec", '""'], 'null', '\n', 0],
  [["-ec", "1,1/0"], 'null', '1\n', 5],
  [["-c", "1,("], 'NOT JSON', '', 3],
  [["-c", "1,unknown_builtin"], 'NOT JSON', '', 3],
  [["-c", "false and unknown_builtin"], 'NOT JSON', '', 3],
  [["-c", "--arg", "x", "123", "--argjson", "y", "123", "[$x,$y]"], 'null', '["123",123]\n', 0],
  [["-c", "--argjson", "x", "1 2", "$x"], 'null', '', 2],
  [["-c", "--argjson", "x", "", "$x"], 'null', '', 2],
  [["-c", "--arg", "x", "one", "--arg", "x", "two", "$x"], 'null', '"one"\n', 0],
  [["."], '{"b":[1,{"a":2}]}', '{\n  "b": [\n    1,\n    {\n      "a": 2\n    }\n  ]\n}\n', 0],
  [["-c"], '{"a":1,"a":2}', '{"a":2}\n', 0],
  [["--raw-output", "--compact-output", "--slurp", "map(.x)"], '{"x":1}\n{"x":2}', '[1,2]\n', 0],
  [["--null-input", "--exit-status", "--", "-1"], 'ignored', '-1\n', 0],
  [["-c", "--arg", "bad-key", "ok", '$ARGS.named["bad-key"],$ARGS.positional'], 'null', '"ok"\n[]\n', 0],
];
for (const [index, [args, input, stdout, status]] of streamCases.entries()) test(`CLI stream/status matrix ${index + 1}`, async () => {
  const result = await run(args, chunks(input));
  assert.equal(result.exitCode, status, result.stderr); assert.equal(result.stdout, stdout);
});

test("whole stream, every byte, and every two-way UTF-8 split agree", async () => {
  const input = Buffer.from('{"s":"A😀B"}\n1e2\n"x\\\"y"\n');
  const expected = '{"s":"A😀B"}\n1E+2\n"x\\\"y"\n';
  for (let split = 0; split <= input.length; split++) {
    const source = (async function* () { yield input.slice(0, split); yield input.slice(split); })();
    const result = await run(["-c", "."], source);
    assert.equal(result.stdout, expected); assert.equal(result.exitCode, 0, result.stderr);
  }
  assert.equal((await run(["-c", "."], chunks(input))).stdout, expected);
  assert.equal((await run(["-c", "."], input)).stdout, expected);
});

test("malformed UTF-8 preserves completed JSON prefix across every chunk split", async () => {
  for (const suffix of [[0xff], [0xc3], [0xc3, 0x28], [0xed, 0xa0, 0x80], [0xf0, 0x80, 0x80, 0x80], [0xf4, 0x90, 0x80, 0x80]]) {
    for (const prefix of ['{}\n', '"😀"\n1\n', '{"a":[1]}\n"incomplete']) {
      const bytes = Buffer.concat([Buffer.from(prefix), Buffer.from(suffix)]);
      const expected = prefix === '{}\n' ? '{}\n' : prefix.startsWith('"😀"') ? '"😀"\n1\n' : '{"a":[1]}\n';
      for (let split = 0; split <= bytes.length; split++) {
        const source = (async function* () { yield bytes.subarray(0, split); yield bytes.subarray(split); })();
        const result = await run(["-c", "."], source);
        assert.equal(result.exitCode, 5); assert.equal(result.stdout, expected, `${suffix} split ${split}`); assert.match(result.stderr, /invalid UTF-8/);
      }
      const single = await run(["-c", "."], chunks(bytes)); assert.equal(single.stdout, expected); assert.equal(single.exitCode, 5);
      const slurp = await run(["-sc", "."], bytes); assert.equal(slurp.stdout, ""); assert.equal(slurp.exitCode, 5);
    }
  }
});

test("compile errors precede stdin iterator creation and data-file effects", async () => {
  let effects = 0;
  const stdin: ByteSource = { [Symbol.asyncIterator]() { effects++; throw new Error("unexpected stdin effect"); } };
  const fs = new MemoryFileSystem();
  fs.readStream = () => { effects++; throw new Error("unexpected file effect"); };
  for (const source of ["", "(", "1,(", "{a:", "[", ".a[", "$missing", "false and unknown", '"\\uD800"', '"\\uDC00"', "1e+", ".a |=", "def f: .; f", ".a[1:2]=[]", "(.[]|select(.>1))|=.+10"]) {
    const result = await run(["-c", source, "data.json"], stdin, {}, { fs });
    assert.equal(result.exitCode, 3, `${source}: ${result.stderr}`); assert.equal(result.stdout, "");
    assert.doesNotMatch(result.stderr, /TypeError|Cannot read|stack/i);
  }
  assert.equal(effects, 0);
});

test("null-input ignores stdin and data files, but still compiles", async () => {
  let effects = 0;
  const input: ByteSource = { [Symbol.asyncIterator]() { effects++; throw new Error("unexpected input"); } };
  const result = await run(["-nsc", ".", "/missing.json"], input);
  assert.equal(result.stdout, "null\n"); assert.equal(effects, 0);
  assert.equal((await run(["-nc", "missing"], input)).exitCode, 3);
});

test("virtual files, relative -f, input order, and filesystem signal propagation", async () => {
  const fs = new MemoryFileSystem();
  await fs.mkdir("/work");
  await fs.writeFile("/work/filter.jq", Buffer.from("# comment\n.x + $offset"));
  await fs.writeFile("/work/one.json", Buffer.from('{"x":1}'));
  await fs.writeFile("/work/two.json", Buffer.from('{"x":2}'));
  const original = fs.readStream.bind(fs);
  const signal = new AbortController().signal;
  const reads: string[] = [];
  fs.readStream = (path, options) => { assert.equal(options?.signal, signal); reads.push(path); return original(path, options); };
  const result = await run(["-c", "--argjson", "offset", "10", "-f", "filter.jq", "one.json", "-", "two.json"], '{"x":3}', {}, { fs, cwd: "/work", signal });
  assert.equal(result.stdout, "11\n13\n12\n"); assert.equal(result.exitCode, 0, result.stderr);
  assert.deepEqual(reads, ["/work/filter.jq", "/work/one.json", "/work/two.json"]);
  assert.equal((await run(["-f", "missing.jq"], "", {}, { fs, signal })).exitCode, 2);
  await fs.writeFile("/bad.jq", Buffer.from("1,(")); reads.length = 0;
  assert.equal((await run(["-f", "/bad.jq", "/work/one.json"], "", {}, { fs, signal })).exitCode, 3);
  assert.deepEqual(reads, ["/bad.jq"]);
});

test("bounded readFile fallback supplies signal and explicit maxBytes", async () => {
  const memory = new MemoryFileSystem();
  await memory.writeFile("/filter", Buffer.from(".")); await memory.writeFile("/data", Buffer.from("1"));
  const signal = new AbortController().signal;
  const observed: number[] = [];
  const fs = new Proxy(memory, { get(target, property) {
    if (property === "readStream") return undefined;
    if (property === "readFile") return async (path: string, options: { signal?: AbortSignal; maxBytes?: number }) => {
      assert.equal(options.signal, signal); assert.equal(typeof options.maxBytes, "number"); observed.push(options.maxBytes!);
      return memory.readFile(path, options);
    };
    const value: unknown = Reflect.get(target, property); return typeof value === "function" ? value.bind(target) : value;
  } });
  const result = await run(["-cf", "/filter"], "", {}, { fs, signal });
  assert.equal(result.exitCode, 2);
  assert.equal((await run(["-c", "-f", "/filter", "/data"], "", {}, { fs, signal })).stdout, "1\n");
  assert.deepEqual(observed, [defaultJqLimits.maxSourceBytes, defaultJqLimits.maxInputBytes]);
});

test("plugin definitions, duplicate registration, replacement, and immutable defaults", async () => {
  const registry = new CommandRegistry(); const host: PluginHost = { commands: registry, use() {}, registerFileSystem() {} };
  assert.deepEqual(createStructuredCommands().map(command => command.name), ["jq"]);
  await structuredCommands().setup(host);
  assert.throws(() => structuredCommands().setup(host), /already registered/);
  await structuredCommands({ replace: true }).setup(host);
  assert.ok(Object.isFrozen(defaultJqLimits));
  for (const value of [0, -1, NaN, Infinity, 1.5]) assert.throws(() => structuredCommands({ limits: { maxSteps: value } }), RangeError);
  assert.throws(() => structuredCommands({ limits: { maxDepth: 257 } }), RangeError);
  assert.throws(() => structuredCommands({ limits: { maxAstDepth: 129 } }), RangeError);
});

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { test } from "node:test";
import { Budget, resolveJqLimits } from "../../../src/commands/structured/limits.js";
import { type JqLimits } from "../../../src/commands/structured/index.js";
import { chunks, run } from "./helpers.js";

test("compact JSON byte accounting is exact at container boundaries", async () => {
  for (const input of ["[0]", '{"a":0}', '"😀"', '["😀"]', "[]", "{}", '{"é":[0]}']) {
    const bytes = Buffer.byteLength(input);
    const result = await run(["-c", "."], chunks(input), { limits: { maxValueBytes: bytes } });
    assert.equal(result.stdout, `${input}\n`, result.stderr);
    assert.equal(result.exitCode, 0, input);
    assert.equal((await run(["-c", "."], input, { limits: { maxValueBytes: bytes - 1 } })).exitCode, 5);
    const budget = new Budget(resolveJqLimits({ maxValueBytes: bytes }), new AbortController().signal);
    assert.equal(budget.value(JSON.parse(input)), bytes);
  }
});

test("valid large decimals survive while malformed JSON and division by zero fail", async () => {
  for (const input of ["NaN", "Infinity", "-Infinity", '"\\uD800"', '"\\uDC00"', '[}', '{"a":}', "01", "1.", "1e", "truefalse", '"bad\nstring"', "[1,]", '{"a":0,}', "\uFEFF0"]) {
    const result = await run(["-c", "."], input);
    assert.equal(result.exitCode, 5, input); assert.equal(result.stdout, "", input);
  }
  for (const bytes of [[255], [0xc3], [0xc3, 0x28], [0xed, 0xa0, 0x80]]) {
    const result = await run(["-c", "."], Uint8Array.from(bytes)); assert.equal(result.exitCode, 5); assert.equal(result.stdout, "");
  }
  for (const filter of ["1/0", "0/0", "1%0"]) {
    const result = await run(["-nc", filter]); assert.equal(result.exitCode, 5, filter); assert.equal(result.stdout, "");
  }
  for (const input of ['1e9999', '[1e9999]', '{"a":1e9999}']) {
    const result = await run(["-c", "."], input);
    assert.equal(result.exitCode, 0, result.stderr);
    assert.equal(result.stdout, `${input.replace("e", "E+")}\n`);
  }
  for (const [filter, expected] of [["1e308*1e308", "1.7976931348623157e+308"], ['"1e9999"|tonumber', '1E+9999'], ['"[1e9999]"|fromjson', '[1E+9999]']]) {
    const result = await run(["-nc", filter!]);
    assert.equal(result.exitCode, 0, result.stderr); assert.equal(result.stdout, `${expected}\n`);
  }
  assert.equal((await run(["-c", "."], '"\\uD83D\\uDE00"')).stdout, '"😀"\n');
});

test("depth limits cover inputs, constructed outputs, and source AST", async () => {
  for (const depth of [7, 8, 9]) {
    const source = "[".repeat(depth) + "0" + "]".repeat(depth);
    const result = await run(["-c", "."], source, { limits: { maxDepth: 8 } });
    assert.equal(result.exitCode, depth <= 8 ? 0 : 5, result.stderr);
  }
  const source = "[".repeat(9) + "0" + "]".repeat(9);
  assert.match((await run(["-nc", source], "", { limits: { maxDepth: 8 } })).stderr, /maxDepth/);
  for (const filter of ["(".repeat(1000) + "0" + ")".repeat(1000), Array(1000).fill(".").join("|"), "." + ".a".repeat(1000)]) {
    const result = await run(["-nc", filter]); assert.match(result.stderr, /maxAstDepth|expected property/); assert.doesNotMatch(result.stderr, /RangeError|call stack/);
  }
});

test("limits protect hidden Cartesian expansion, collections, and emitted results", async () => {
  const product = Array(12).fill("(0,1)").join("|");
  assert.equal((await run(["-nc", `[${product}]|length`])).stdout, "4096\n");
  const probes: [string, Partial<JqLimits>, string][] = [
    [`${product}|select(false)`, { maxSteps: 100 }, "maxSteps"],
    [`[${product}]`, { maxCollectionSize: 32 }, "maxCollectionSize"],
    [product, { maxResults: 8 }, "maxResults"],
    [".[1000]=0", { maxCollectionSize: 32 }, "maxCollectionSize"],
    ['("x"*1000000)?', { maxValueBytes: 64 }, "maxValueBytes"],
    ['[range(1000)|"x"*32]', { maxValueBytes: 128 }, "maxValueBytes"],
    ['[range(100)]|map("x"*32)', { maxValueBytes: 512 }, "maxValueBytes"],
    ['[range(100)]|sort_by("x"*32)', { maxValueBytes: 512 }, "maxValueBytes"],
  ];
  for (const [filter, limits, error] of probes) {
    const result = await run(["-nc", filter], "", { limits });
    assert.equal(result.exitCode, 5, filter); assert.match(result.stderr, new RegExp(error));
  }
});

test("input, source, output, slurp and result budgets enforce boundary values", async () => {
  assert.equal((await run(["."], "0 ", { limits: { maxInputBytes: 2 } })).stdout, "0\n");
  assert.match((await run(["."], "0  ", { limits: { maxInputBytes: 2 } })).stderr, /maxInputBytes/);
  assert.equal((await run(["-nc", "1+1"], "", { limits: { maxSourceBytes: 3 } })).stdout, "2\n");
  assert.match((await run(["-nc", "1+1"], "", { limits: { maxSourceBytes: 2 } })).stderr, /maxSourceBytes/);
  assert.equal((await run(["-nc", "0"], "", { limits: { maxOutputBytes: 2 } })).stdout, "0\n");
  assert.match((await run(["-nc", "0"], "", { limits: { maxOutputBytes: 1 } })).stderr, /maxOutputBytes/);
  const limited = await run(["-nc", "0,1"], "", { limits: { maxOutputBytes: 2 } });
  assert.equal(limited.stdout, "0\n"); assert.match(limited.stderr, /maxOutputBytes/);
  assert.equal((await run(["-sc", "."], "0 1", { limits: { maxValueBytes: 5 } })).stdout, "[0,1]\n");
  assert.match((await run(["-sc", "."], "0 1", { limits: { maxValueBytes: 4 } })).stderr, /maxValueBytes/);
  assert.match((await run(["-nc", "0,1"], "", { limits: { maxResults: 1 } })).stderr, /maxResults/);
});

test("hazardous expansion cases have a one-second killable outer deadline", () => {
  for (const scenario of ["source", "json", "expansion", "allocation", "cancel"]) {
    const result = spawnSync(process.execPath, ["--import", "tsx", new URL("./hazard-worker.ts", import.meta.url).pathname, scenario], { encoding: "utf8", timeout: 1000, maxBuffer: 4096 });
    assert.ifError(result.error); assert.equal(result.status, 0, `${scenario}: ${result.stderr}`); assert.equal(result.stdout.trim(), "ok");
  }
});

import assert from "node:assert/strict";
import { setImmediate, setTimeout as delay } from "node:timers/promises";
import { test } from "node:test";
import type { ByteSource, CommandContext } from "../../../src/contracts/index.js";
import { MemoryFileSystem } from "../../../src/fs/memory/index.js";
import { execute } from "./harness.js";

async function* split(bytes: Uint8Array, size: number): ByteSource {
  for (let offset = 0; offset < bytes.length; offset += size) yield bytes.subarray(offset, offset + size);
}

const malformed = [
  '[1,]', '{"x":}', '{"x" 1}', '{"x":1,}', '[true false]', '[01]', '[1e]', 'truefalse', '1e+',
  '0x10', '"bad\nstring"', '"\\q"', '"\\u12"', '"\\uD800"', '"\\uDC00"', '\uFEFF0', 'null\u0000',
  '[}', '[[[]]', '{"x": [1}', '1e9999', '-Infinity', 'NaN',
];
for (const [index, input] of malformed.entries()) test(`${input === '1e9999' ? 'valid large exponent' : 'strict malformed JSON'} ${index} across chunk boundaries`, { timeout: 3000 }, async () => {
  for (const size of [1, 2, 5, 64]) {
    const result = await execute(['-c', '.'], split(Buffer.from(input), size));
    assert.equal(result.status, input === '1e9999' ? 0 : 5, JSON.stringify({ input, size, result }));
    assert.equal(result.stdout, input === '1e9999' ? '1E+9999\n' : '');
    if (input === '1e9999') assert.equal(result.stderr, '');
    else assert.match(result.stderr, /^jq: /u);
  }
});

test('malformed suffix preserves completed prefix but slurp remains atomic', async () => {
  for (const suffix of ['[1,]', '"\\uD800"', 'truefalse']) for (const size of [1, 3, 64]) {
    for (const flags of [['-c'], ['-sc']]) {
      const result = await execute([...flags, '.'], split(Buffer.from(`{"ok":1}\n${suffix}`), size));
      assert.equal(result.status, 5);
      assert.equal(result.stdout, flags[0] === '-sc' ? '' : '{"ok":1}\n');
    }
  }
});

test('invalid UTF-8 never becomes replacement text', async () => {
  for (const invalid of [[0xc0, 0xaf], [0xed, 0xa0, 0x80], [0xf4, 0x90, 0x80, 0x80], [0xf0, 0x9f], [0x80]]) {
    const bytes = Buffer.concat([Buffer.from('{}\n'), Buffer.from(invalid)]);
    for (const size of [1, 2, 64]) {
      const result = await execute(['-c', '.'], split(bytes, size));
      assert.equal(result.status, 5);
      assert.equal(result.stdout, '{}\n');
      assert.match(result.stderr, /UTF-8/u);
    }
  }
});

const preflight: readonly [readonly string[], number][] = [
  [['-c', '1,('], 3], [['-c', 'if true then 1 else $missing end'], 3], [['-c', 'false and nope'], 3],
  [['-c', '"\\q"'], 3], [['-c', '.foo='], 3], [['-c', 'sort_by()'], 3], [['-c', '.[0:1]=0'], 3],
  [['-c', '.[]? |= 0'], 3], [['-c', 'join(",";":")'], 3], [['-RZ', '.'], 2], [['--raw-input=lines', '.'], 2],
  [['--argjson', 'x', '{"bad":}', '$x'], 2], [['--argjson', 'x', '1 2', '$x'], 2],
];
for (const [index, [argv, status]] of preflight.entries()) test(`preflight ${index} acquires no input or data files`, async () => {
  let acquired = 0;
  let opened = 0;
  const stdin: ByteSource = { [Symbol.asyncIterator]() { acquired++; throw new Error('unexpected stdin acquisition'); } };
  const fs = new Proxy(new MemoryFileSystem(), { get(target, property) {
    if (property === 'readFile' || property === 'readStream') return () => { opened++; throw new Error('unexpected data file read'); };
    const member: unknown = Reflect.get(target, property);
    return typeof member === 'function' ? member.bind(target) : member;
  } });
  const result = await execute([...argv, '/must-not-open'], stdin, {}, { fs });
  assert.equal(result.status, status, result.stderr);
  assert.equal(result.stdout, '');
  assert.equal(acquired, 0);
  assert.equal(opened, 0);
});

test('null input ignores invalid stdin and missing data files', async () => {
  const stdin: ByteSource = { [Symbol.asyncIterator]() { throw new Error('unexpected stdin acquisition'); } };
  const result = await execute(['-nsc', '.', '/missing'], stdin);
  assert.deepEqual(result, { status: 0, stdout: 'null\n', stderr: '' });
});

test('virtual argv preserves NUL without invoking a host process', async () => {
  const result = await execute(['-nr', '--arg', 'value', 'a\u0000b', '$value']);
  assert.deepEqual(result, { status: 0, stdout: 'a\u0000b\n', stderr: '' });
});

test('empty last remains distinct from empty first under exit-status mode', async () => {
  assert.deepEqual(await execute(['-ne', 'last(empty)']), { status: 1, stdout: 'null\n', stderr: '' });
  assert.deepEqual(await execute(['-ne', 'first(empty)']), { status: 4, stdout: '', stderr: '' });
});

test('result and UTF-8 output limits preserve exact emitted prefixes', async () => {
  const results = await execute(['-nc', 'range(20)'], '', { limits: { maxResults: 3 } });
  assert.equal(results.status, 5);
  assert.equal(results.stdout, '0\n1\n2\n');
  assert.match(results.stderr, /maxResults/u);
  const exact = await execute(['-nr', '"😀"'], '', { limits: { maxOutputBytes: 5 } });
  assert.equal(exact.stdout, '😀\n');
  assert.equal(exact.status, 0);
  const short = await execute(['-nr', '"😀"'], '', { limits: { maxOutputBytes: 4 } });
  assert.equal(short.stdout, '');
  assert.equal(short.status, 5);
  assert.match(short.stderr, /maxOutputBytes/u);
});

test('limits cannot be swallowed by optional filters or hidden products', async () => {
  const cases = [
    { filter: '([range(1000)])?', limits: { maxCollectionSize: 8 }, message: /maxCollectionSize/u },
    { filter: '([range(100000)]|empty)?', limits: { maxSteps: 64 }, message: /maxSteps/u },
    { filter: '.[1000000]=0', limits: { maxCollectionSize: 8 }, message: /maxCollectionSize/u },
    { filter: '("😀"*1000000)?', limits: { maxValueBytes: 32 }, message: /maxValueBytes/u },
    { filter: '[range(32)]|sort_by([range(32)])', limits: { maxValueBytes: 256 }, message: /maxValueBytes/u },
  ];
  for (const fixture of cases) {
    const result = await execute(['-nc', fixture.filter], '', { limits: fixture.limits });
    assert.equal(result.status, 5, fixture.filter);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, fixture.message);
  }
});

test('bounded generators remain lazy after index and slice fixes', async () => {
  for (const filter of ['first([42][range(1000000)])', 'first([42][range(1000000):1])', 'first([42][0:range(1;1000000)])']) {
    const result = await execute(['-nc', filter], '', { limits: { maxSteps: 128, maxCollectionSize: 8 } });
    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stdout, filter.includes(':') ? '[42]\n' : '42\n');
  }
});

test('stalled reads and writes abort and observe late host rejections', { timeout: 3000 }, async () => {
  for (const operation of ['read', 'write'] as const) {
    const controller = new AbortController();
    const reason = new Error(`independent ${operation} abort`);
    let entered!: () => void;
    let rejectLate!: (error: Error) => void;
    const ready = new Promise<void>(resolve => { entered = resolve; });
    const pending = () => { entered(); return new Promise<never>((_, reject) => { rejectLate = reject; }); };
    const stdin: ByteSource = { [Symbol.asyncIterator]() { return { next: pending }; } };
    const overrides: Partial<CommandContext> = { signal: controller.signal, ...(operation === 'write' ? { stdout: { write: pending } } : {}) };
    const running = execute(operation === 'read' ? ['.'] : ['-n', '.'], stdin, {}, overrides);
    const rejected = assert.rejects(running, error => error === reason);
    await ready;
    controller.abort(reason);
    await rejected;
    rejectLate(new Error('late failure must be observed'));
    await delay(0);
  }
});

test('CPU expansion cooperatively observes cancellation', { timeout: 3000 }, async () => {
  const controller = new AbortController();
  const reason = new Error('independent CPU cancellation');
  const running = execute(['-nc', 'range(1000000000)|empty'], '', { limits: { maxSteps: 10000000 } }, { signal: controller.signal });
  const rejected = assert.rejects(running, error => error === reason);
  await setImmediate();
  controller.abort(reason);
  await rejected;
});

test('seeded JSON roundtrips tolerate every selected byte split', { timeout: 10000 }, async () => {
  let seed = 0x6d2b79f5;
  const random = (maximum: number) => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % maximum; };
  const strings = ['😀', 'é', '\u0000', '\n\t"\\', '__proto__', 'constructor', '', '2'];
  const value = (depth: number): unknown => {
    const kind = random(depth ? 6 : 4);
    if (kind === 0) return null;
    if (kind === 1) return random(2) !== 0;
    if (kind === 2) return (random(201) - 100) / 8;
    if (kind === 3) return strings[random(strings.length)];
    if (kind === 4) return Array.from({ length: random(5) }, () => value(depth - 1));
    return Object.fromEntries(Array.from({ length: random(5) }, () => [strings[random(strings.length)]!, value(depth - 1)]));
  };
  for (let round = 0; round < 64; round++) {
    const input = JSON.stringify(value(3));
    for (const size of [1, 2, 7, 64]) {
      const result = await execute(['-c', '.'], split(Buffer.from(input), size));
      assert.deepEqual(result, { status: 0, stdout: `${input}\n`, stderr: '' }, `seed 0x6d2b79f5 round ${round} chunk ${size}`);
    }
  }
  assert.equal(Object.hasOwn(Object.prototype, 'polluted'), false);
});

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { MemoryFileSystem } from "../../../src/fs/memory/index.js";
import { execute } from "./harness.js";

interface RawFixture {
  id: string;
  argv: string[];
  inputHex: string;
  files?: { path: string; inputHex: string }[];
  stdout: string;
  status: number;
  policy?: string;
  policyStdout?: string;
  policyStatus?: number;
}
const corpus = JSON.parse(readFileSync(new URL("./raw-input-native.json", import.meta.url), "utf8")) as { cases: RawFixture[] };
async function* chunks(bytes: Uint8Array, size: number) {
  for (let offset = 0; offset < bytes.length; offset += size) yield bytes.subarray(offset, offset + size);
}
for (const fixture of corpus.cases) test(`raw native: ${fixture.id}`, async () => {
  for (const size of [1, 2, 7, 16384]) {
    const fs = new MemoryFileSystem();
    for (const file of fixture.files ?? []) await fs.writeFile(`/${file.path}`, Buffer.from(file.inputHex, "hex"));
    const input = chunks(Buffer.from(fixture.inputHex, "hex"), size);
    const result = await execute(fixture.argv, input, {}, { fs });
    assert.equal(result.status, fixture.policyStatus ?? fixture.status, `${fixture.id} chunk ${size}: ${result.stderr}`);
    assert.equal(result.stdout, fixture.policyStdout ?? fixture.stdout, `${fixture.id} chunk ${size}`);
    if (fixture.policy?.startsWith("strict-utf8")) assert.match(result.stderr, /invalid UTF-8/u);
    else if (fixture.policy) assert.match(result.stderr, /^jq: .{1,1000}\n$/u);
    else if (fixture.status < 5) assert.equal(result.stderr, "");
    else assert.match(result.stderr, /^jq: .{1,1000}\n$/u);
  }
});

import assert from "node:assert/strict";
import { setImmediate } from "node:timers/promises";
import { test } from "node:test";
import { type ByteSource } from "../../../../src/contracts/index.js";
import { type JqLimits } from "../../../../src/commands/structured/index.js";
import { allVectors, executeBytes, expectedBytes } from "./harness.js";

const reference = (id: string) => {
  const vector = allVectors.find(vector => vector.id === id);
  assert.ok(vector, id);
  return vector;
};

for (const id of ["unicode-records", "unicode-slurp", "json-multibyte", "json-surrogate-pair", "raw-nul"]) {
  test(`every split plus empty chunks preserves native bytes: ${id}`, { timeout: 3000 }, async () => {
    const vector = reference(id);
    const input = Buffer.from(vector.inputHex, "hex");
    for (let cut = 0; cut <= input.length; cut++) {
      async function* source() { yield input.subarray(0, cut); yield new Uint8Array(); yield input.subarray(cut); }
      assert.deepEqual(await executeBytes(vector.argv!, source()), expectedBytes(vector), `split ${cut}`);
    }
  });
}

test("UTF-8 crossing the internal 16384-byte scan boundary preserves native bytes", { timeout: 3000 }, async () => {
  const vector = reference("chunk-edge-reference");
  const input = Buffer.from(vector.inputHex, "hex");
  for (const cut of [16382, 16383, 16384, 16385, 16386, 16387]) {
    async function* source() { yield input.subarray(0, cut); yield new Uint8Array(); yield input.subarray(cut); }
    assert.deepEqual(await executeBytes(vector.argv!, source()), expectedBytes(vector), `split ${cut}`);
  }
});

for (const id of ["raw-lone-continuation", "raw-truncated", "raw-bad-continuation", "json-bad-string"]) {
  test(`strict UTF-8 rejection remains chunk invariant (not native parity): ${id}`, async () => {
    const vector = reference(id);
    const input = Buffer.from(vector.inputHex, "hex");
    const baseline = await executeBytes(vector.argv!, input);
    assert.equal(baseline.status, 5);
    assert.match(Buffer.from(baseline.stderrHex, "hex").toString(), /invalid UTF-8/u);
    for (let cut = 0; cut <= input.length; cut++) {
      async function* source() { yield input.subarray(0, cut); yield new Uint8Array(); yield input.subarray(cut); }
      assert.deepEqual(await executeBytes(vector.argv!, source()), baseline, `split ${cut}`);
    }
  });
}

for (const [id, limit, bytes] of [
  ["join-quota-prefix", "maxOutputBytes", 15],
  ["join-json-quota-reference", "maxOutputBytes", 8],
  ["join-unicode-separator", "maxOutputBytes", 8],
  ["raw-quota-reference", "maxOutputBytes", 4],
  ["raw-quota-reference", "maxValueBytes", 5],
] as const) {
  test(`exact ${limit} boundary retains native output: ${id}`, async () => {
    const vector = reference(id);
    const actual = await executeBytes(vector.argv!, Buffer.from(vector.inputHex, "hex"), { limits: { [limit]: bytes } });
    assert.deepEqual(actual, expectedBytes(vector));
    const short = await executeBytes(vector.argv!, Buffer.from(vector.inputHex, "hex"), { limits: { [limit]: bytes - 1 } });
    assert.equal(short.status, 5);
    assert.match(Buffer.from(short.stderrHex, "hex").toString(), new RegExp(limit));
    const native = Buffer.from(vector.expected.stdoutHex, "hex");
    const prefix = Buffer.from(short.stdoutHex, "hex");
    assert.deepEqual(prefix, native.subarray(0, prefix.length));
  });
}

const quotaCases: { name: keyof JqLimits; input: string; argv: string[]; value: number }[] = [
  { name: "maxInputBytes", input: `${"x".repeat(60)}\n`, argv: ["-Rj", "."], value: 50 },
  { name: "maxValueBytes", input: "x".repeat(20), argv: ["-Rj", "."], value: 12 },
  { name: "maxOutputBytes", input: '["雪","x"]', argv: ["-j", 'join("/")'], value: 4 },
  { name: "maxSourceBytes", input: "", argv: ["-nj", 'join("/")'], value: 4 },
  { name: "maxDepth", input: '[[["x"]]]', argv: ["-c", "."], value: 2 },
  { name: "maxAstDepth", input: "", argv: ["-nc", "[[[[1]]]]"], value: 2 },
  { name: "maxSteps", input: "", argv: ["-nc", "[range(1000)]?"], value: 40 },
  { name: "maxResults", input: '["雪","x"]', argv: ["-j", 'join(("/","|","!"))?'], value: 1 },
  { name: "maxCollectionSize", input: '["a","b","c","d"]', argv: ["-j", 'join("/")?'], value: 3 },
];
for (const fixture of quotaCases) test(`uncatchable quota: ${fixture.name}`, { timeout: 2500 }, async () => {
  const result = await executeBytes(fixture.argv, Buffer.from(fixture.input), { limits: { [fixture.name]: fixture.value } });
  assert.equal(result.status, 5);
  assert.match(Buffer.from(result.stderrHex, "hex").toString(), new RegExp(fixture.name));
  if (fixture.name === "maxResults") assert.equal(result.stdoutHex, reference("join-quota-prefix").expected.stdoutHex.slice(0, 10));
  else assert.equal(result.stdoutHex, "");
});

test("raw backpressure precedes later generator error and cancels blocked write", { timeout: 3000 }, async () => {
  const controller = new AbortController();
  const reason = new Error("independent write cancellation");
  let reads = 0;
  let cleanups = 0;
  let errors = 0;
  let entered!: () => void;
  let rejectLate!: (reason: Error) => void;
  const ready = new Promise<void>(resolve => { entered = resolve; });
  const input: ByteSource = { [Symbol.asyncIterator]() { return {
    async next() { reads++; return { done: false, value: Buffer.from("雪\nsecond\n") }; },
    async return() { cleanups++; return { done: true, value: undefined }; },
  }; } };
  const running = executeBytes(["-Rj", '[.]|join(("/",1/0))'], input, {}, {
    signal: controller.signal,
    stdout: { write(bytes) {
      assert.equal(Buffer.from(bytes).toString("hex"), reference("raw-quota-reference").expected.stdoutHex.slice(0, 6));
      entered();
      return new Promise<never>((_, reject) => { rejectLate = reject; });
    } },
    stderr: { async write() { errors++; } },
  });
  const rejected = assert.rejects(running, error => error === reason);
  await ready;
  await setImmediate();
  assert.equal(reads, 1);
  assert.equal(errors, 0);
  controller.abort(reason);
  await rejected;
  rejectLate(new Error("late sink failure"));
  await setImmediate();
  assert.equal(cleanups, 1);
  assert.equal(errors, 0);
});

test("partial multibyte input cancels pending read and observes late rejection", { timeout: 3000 }, async () => {
  const controller = new AbortController();
  const reason = new Error("independent read cancellation");
  let reads = 0;
  let cleanups = 0;
  let entered!: () => void;
  let rejectLate!: (reason: Error) => void;
  const ready = new Promise<void>(resolve => { entered = resolve; });
  const source: ByteSource = { [Symbol.asyncIterator]() { return {
    next() {
      if (++reads === 1) return Promise.resolve({ done: false as const, value: Buffer.from([0xf0, 0x9f]) });
      entered();
      return new Promise<IteratorResult<Uint8Array>>((_, reject) => { rejectLate = reject; });
    },
    async return() { cleanups++; return { done: true, value: undefined }; },
  }; } };
  const running = executeBytes(["-Rsj", "."], source, {}, { signal: controller.signal });
  const rejected = assert.rejects(running, error => error === reason);
  await ready;
  controller.abort(reason);
  await rejected;
  rejectLate(new Error("late input failure"));
  await setImmediate();
  assert.equal(cleanups, 1);
});

test("cancellation interrupts separator generation before quota exhaustion", { timeout: 3000 }, async () => {
  const controller = new AbortController();
  let writes = 0;
  const reason = new Error("independent CPU cancellation");
  const running = executeBytes(["-nj", '[],[]|join(range(1000000000))'], Buffer.alloc(0), { limits: { maxSteps: 100000000, maxResults: 10000000 } }, {
    signal: controller.signal,
    stdout: { async write() { if (++writes === 1) setTimeout(() => controller.abort(reason), 0); } },
  });
  await assert.rejects(running, error => error === reason);
  assert.ok(writes > 0 && writes < 10000000);
});

test("pre-aborted execution does not acquire input", async () => {
  let acquired = 0;
  const reason = new Error("already cancelled");
  const input: ByteSource = { [Symbol.asyncIterator]() { acquired++; throw new Error("unexpected read"); } };
  await assert.rejects(executeBytes(["-Rj", "."], input, {}, { signal: AbortSignal.abort(reason) }), error => error === reason);
  assert.equal(acquired, 0);
});
